"""Build a private, local-only dictionary audition/review page; no credentials."""
import argparse,json
from pathlib import Path
from .validate import read_jsonl,read_results,validate_draft,canonical_sha

HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Crow Chinese Dictionary · review</title><link rel="stylesheet" href="style.css"><body><header><h1>Crow Chinese Dictionary</h1><p>Source-attested candidates and dictionary drafts · local review</p><p id="stats"></p><input id="search" aria-label="Find a candidate" placeholder="Find a word, reading or definition"><button id="save">Save review decisions</button></header><main><nav id="list" aria-label="Candidates"></nav><article id="entry"><p>Select a candidate.</p></article></main><script src="app.js"></script></body></html>'''
CSS='''*{box-sizing:border-box}body{margin:0;background:#f6f6ef;color:#243025;font:16px/1.65 system-ui,sans-serif}header{padding:24px;border-bottom:1px solid #d4dbcd}h1{margin:0;font-weight:550}p{margin:8px 0}button,input{font:inherit;border:1px solid #bcc9b5;border-radius:8px;padding:10px 12px;background:white;color:inherit}button{cursor:pointer;margin:4px 6px 4px 0}button:disabled{opacity:.5;cursor:default}input{width:min(100%,500px)}main{display:grid;grid-template-columns:280px 1fr;min-height:65vh}nav{max-height:80vh;overflow:auto;border-right:1px solid #d4dbcd;padding:16px}nav button{display:block;width:100%;text-align:left;margin-bottom:10px}nav button.active{background:#e4edda}article{padding:24px;max-width:1000px;overflow-wrap:anywhere}h2{font-size:36px;margin:0}h3{margin-top:28px}.reading{color:#526f3d;font-size:22px}.status{background:#e8eddf;border-radius:8px;padding:8px 12px;margin:16px 0}.source{padding:12px 0;border-top:1px solid #d4dbcd}.muted{font-size:14px;color:#5d6958}.actions{margin:24px 0}a{color:#466b34}@media(max-width:650px){main{grid-template-columns:1fr}nav{max-height:240px;border-bottom:1px solid #d4dbcd;border-right:0}article{padding:16px}}'''
JS='''let rows=[],selected=null;const decisions=new Map(),$=s=>document.querySelector(s);const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
function list(){const q=$('#search').value.toLocaleLowerCase();const n=$('#list');n.replaceChildren();for(const row of rows.filter(r=>JSON.stringify([r.word,r.reading,r.targetLanguage,r.draft]).toLocaleLowerCase().includes(q)).slice(0,500)){const b=node('button',row.word+' · '+row.reading+' · '+row.targetLanguage);b.classList.toggle('active',row.jobId===selected);b.onclick=()=>show(row);n.append(b)}}
function show(row){selected=row.jobId;list();const a=$('#entry');a.replaceChildren(node('h2',row.word),node('p',row.reading+' · '+row.spokenLanguage+' → '+row.targetLanguage,'reading'));a.append(node('div',row.draft?(row.generatorModel==='source-import'?'Source import: ':'Machine draft: ')+(row.issues.length?row.issues.join(', '):'structural checks passed; semantic review still needed'):'Not generated. Evidence is shown below.','status'));if(row.draft){a.append(node('h3','Proposed meanings'));for(const sense of row.draft.senses||[]){a.append(node('p',sense.definition),node('p',[sense.pos,sense.register,'Sources: '+sense.sourceRefs.join(', ')].filter(Boolean).join(' · '),'muted'))}if(row.draft.abstainReason)a.append(node('p','Model abstained: '+row.draft.abstainReason))}if(row.holdReasons.length)a.append(node('p','Held: '+row.holdReasons.join(', '),'status'));a.append(node('h3','Source evidence'));for(const e of row.evidence){const section=node('section',undefined,'source');section.append(node('strong',e.sourceId+' · '+e.language));if(e.sourcePos)section.append(node('p',e.sourcePos,'muted'));if(e.rawSourceSenses?.length){for(const sense of e.rawSourceSenses){const labels=[...(sense.tags||[]),...(sense.raw_tags||[])].join(', ');section.append(node('p',(labels?'('+labels+') ':'')+(sense.glosses||[]).join('; ')))}}else section.append(node('p',e.definition));section.append(node('p',e.license+' · '+e.attribution,'muted'));if(/^https?:\\/\\//.test(e.sourceUrl)){const link=node('a','Source website');link.href=e.sourceUrl;link.rel='noreferrer';link.target='_blank';section.append(link)}a.append(section)}const actions=node('div',undefined,'actions');for(const [decision,label]of [['approve','Approve this exact draft'],['reject','Reject'],['uncertain','Keep uncertain']]){const b=node('button',label);b.disabled=!row.draft||!!row.issues.length;b.onclick=()=>{decisions.set(row.jobId,{jobId:row.jobId,draftSha256:row.draftSha256,evidenceHash:row.evidenceHash,decision,reviewType:'human',reviewer:'local-human',generatorModel:row.generatorModel,notes:'Explicit local review decision'});status()};actions.append(b)}a.append(actions);status()}
function status(){$('#stats').textContent=rows.length+' candidates · '+rows.filter(r=>r.draft).length+' drafts · '+decisions.size+' explicit review decisions. Source attestations and automated checks do not prove every meaning is correct.'}
$('#search').addEventListener('input',list);$('#save').onclick=()=>{const blob=new Blob([[...decisions.values()].map(x=>JSON.stringify(x)).join('\\n')+'\\n'],{type:'application/x-ndjson'}),a=node('a');a.href=URL.createObjectURL(blob);a.download='crow-review-decisions.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
fetch('data.json').then(r=>{if(!r.ok)throw Error('Cannot load local review data');return r.json()}).then(data=>{rows=data.entries;list();status();if(rows.length)show(rows[0])}).catch(e=>$('#entry').replaceChildren(node('p',e.message)));
'''

def build(jobs_path,results_path,out):
    jobs={j.get('jobId',j.get('id')):j for j in read_jsonl(jobs_path)};results={}
    if results_path and Path(results_path).exists():
        for r in read_results(results_path,jobs):results[r['jobId']]=r
    entries=[]
    for key,job in jobs.items():
        result=results.get(key);issues=[];dh='';eh=job['evidenceHash']
        if result:issues,_,dh,eh=validate_draft(job,result)
        entries.append(dict(jobId=key,word=job['canonicalWord'],reading=job['reading'],spokenLanguage=job['spokenLanguage'],targetLanguage=job['targetLanguage'],evidence=job['evidence'],holdReasons=job.get('holdReasons',[]),draft=result['draft'] if result else None,generatorModel=result.get('generatorModel','') if result else '',draftSha256=dh,evidenceHash=eh,issues=issues))
    out=Path(out);out.mkdir(parents=True,exist_ok=True)
    for name,text in [('index.html',HTML),('style.css',CSS),('app.js',JS),('data.json',json.dumps({'entries':entries},ensure_ascii=False))]:(out/name).write_text(text)
    return {'entries':len(entries),'drafts':len(results)}

def main(argv=None):
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--jobs',type=Path,required=True);p.add_argument('--results',type=Path);p.add_argument('--out',type=Path,default=Path('work/review'));a=p.parse_args(argv);print(json.dumps(build(a.jobs,a.results,a.out)))
if __name__=='__main__':main()
